/*
Day #1 Tangent
https://openprocessing.org/sketch/2378849
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let sc1, sc2;
const FPS = 30; // frames per second
const FPT = 60; // frames per transition

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(FPS);
	describe("tangent lines of two random bezier curves, colored in the corresponding angle");
	colorMode(HSB);
	background("rgb(0,0,12)");
	noFill();
	// if (frameCount === 0) // noLoop() removed for animation
	sc1 = genBezs(2);
	sc2 = genBezs(2);
	if (!isLooping()) redraw();
}

function genBezs(n = 1) {
	let bezs = [];
	for (let i = 0; i < n; i++) {
		const p1 = {x: 0, y: ~~(random(0, 0.3) * height)};
		const p2 = {x: ~~(random(0.25, 0.6)*width), y: ~~(random(1) * height)};
		const p3 = {x: ~~(random(0.4, 0.75)*width), y: ~~(random(1) * height)};
		const p4 = {x: width, y: ~~(random(0.7, 1)*height)};
		const pts = [p1, p2, p3, p4];
		for (const p of pts) {
			p.x = ~~random(width);
			p.y = ~~random(height);
		}
		bezs[i] = pts;
	}
	return bezs;
}

function draw() {
	background("rgb(0,0,8)");
	if (frameCount % FPT === 0) {
		[sc1,sc2] = [sc2, genBezs(2)];
	}
	const t = fract(frameCount / FPT);
	const bez = lerpBez(sc1, sc2, t);
	drawTangents(bez);
}

function lerpBez(sc1, sc2, t) {
	var bezs = [];
	for (let i = 0; i < sc1.length; i++) {
		var pts = [];
		for (let j = 0; j < 4; j++) {
			const p = {x: lerp(sc1[i][j].x, sc2[i][j].x, t), y: lerp(sc1[i][j].y, sc2[i][j].y, t)};
			pts[j] = p;
		}
		bezs.push(pts);
	}
	return bezs;
}

function drawTangents(bezs) {
	// https://p5js.org/reference/p5/bezierTangent/
	for (let bez of bezs) {
		var p1, p2, p3, p4;
		[p1, p2, p3, p4] = bez;

		strokeWeight(3);
		stroke("rgba(139,0,0,0.5)");
		// bezier(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, p4.x, p4.y)

		strokeWeight(1);
		stroke(255, 96);
		for (let f = 0; f <= 1; f += 0.004) {
			const x = bezierPoint(p1.x, p2.x, p3.x, p4.x, f);
			const y = bezierPoint(p1.y, p2.y, p3.y, p4.y, f);

			// Top-right tangent line.
			// Scale the tangent point to draw a shorter line.
			let tx = 2 * bezierTangent(p1.x, p2.x, p3.x, p4.x, f);
			let ty = 2 * bezierTangent(p1.y, p2.y, p3.y, p4.y, f);
			const vec = createVector(tx, ty).normalize().mult(0.3*max(width, height)); // mult(2*max(width, height));
			const ang = vec.heading();
			const clrDevi = 60 * (noise((x+tx)/1234, (y+ty)/4321, frameCount/22)-0.5);
			stroke(~~(ang/TWO_PI*360 + clrDevi + 360) % 360, 75, 75, 0.25);
			line(x + vec.x, y + vec.y, x - vec.x, y - vec.y);
		}
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}
function doubleClicked() {
	if (mouseButton === LEFT) setup();
}
function mousePressed() {
	if (mouseButton !== LEFT) return;
	  if (isLooping()) {
    // noLoop() removed for animation
  } else {
    loop();
  }
}
